// JSON与typed必须同形；拒重键/未知分类/重复取得，权源仍由早实序与晚教学门完整验证。
#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "military_tactic_learning_codec.hpp"
#include "military_officer_codec.hpp"
#include "resident/domains/conditions/domain_codec_util.hpp"
#include "resident/storage/common_checkpoint.hpp"
namespace hanmo::resident::military_tactic_learning_codec {
namespace {
using namespace domain_codec;
const std::vector<StableId> kinds{"authored_initial","teaching","practice"};
Status emit_acquisition(ProjectionWriter& w,const MilitaryTacticAcquisitionFact& f){const auto kind=static_cast<unsigned>(f.source_kind);if(kind>=kinds.size())return w.reject("MilitaryTacticAcquisitionShapeMismatch",f.id);w.field("id",f.id);w.field("actor_id",f.actor_id);w.field("tactic_id",f.tactic_id);w.field("source_id",f.source_id);w.field("source_kind",kinds[kind]);w.field("tick",f.tick);w.order_fields(f.field_order);return w.status();}
MilitaryTacticAcquisitionFact read(const V& v){const StableId path="military_tactic_learning/acquisitions";boundary::fields(v,{"id","actor_id","tactic_id","source_id","source_kind","tick"},{},path);MilitaryTacticAcquisitionFact f;f.field_order=boundary::order(v);f.id=boundary::get_string(v,"id",path);f.actor_id=boundary::get_string(v,"actor_id",path);f.tactic_id=boundary::get_string(v,"tactic_id",path);f.source_id=boundary::get_string(v,"source_id",path);const auto kind=boundary::get_string(v,"source_kind",path);auto at=std::find(kinds.begin(),kinds.end(),kind);if(at==kinds.end())boundary::fail("MilitaryTacticAcquisitionShapeMismatch",path);f.source_kind=static_cast<MilitaryTacticLearningSourceKind>(at-kinds.begin());f.tick=boundary::get_int(v,"tick",path);return f;}
Status walk(CodecVisitor& c,MilitaryTacticAcquisitionFact& f){c.field("id",f.id);c.field("actor_id",f.actor_id);c.field("tactic_id",f.tactic_id);c.field("source_id",f.source_id);Integer kind=static_cast<Integer>(f.source_kind);c.field("source_kind",kind);if(kind<0||kind>2)return c.reject("MilitaryTacticAcquisitionShapeMismatch",f.id);f.source_kind=static_cast<MilitaryTacticLearningSourceKind>(kind);c.field("tick",f.tick);common_checkpoint::strings(c,"field_order",f.field_order);return c.status();}
Status emit_practice(ProjectionWriter& w,const MilitaryTacticPracticeFact& f){w.field("id",f.id);w.field("actor_id",f.actor_id);w.field("tactic_id",f.tactic_id);w.field("training_action_id",f.training_action_id);w.field("tick",f.tick);w.order_fields(f.field_order);return w.status();}
MilitaryTacticPracticeFact read_practice(const V& v){const StableId path="military_tactic_learning/practices";boundary::fields(v,{"id","actor_id","tactic_id","training_action_id","tick"},{},path);MilitaryTacticPracticeFact f;f.field_order=boundary::order(v);f.id=boundary::get_string(v,"id",path);f.actor_id=boundary::get_string(v,"actor_id",path);f.tactic_id=boundary::get_string(v,"tactic_id",path);f.training_action_id=boundary::get_string(v,"training_action_id",path);f.tick=boundary::get_int(v,"tick",path);return f;}
Status walk(CodecVisitor& c,MilitaryTacticPracticeFact& f){c.field("id",f.id);c.field("actor_id",f.actor_id);c.field("tactic_id",f.tactic_id);c.field("training_action_id",f.training_action_id);c.field("tick",f.tick);common_checkpoint::strings(c,"field_order",f.field_order);return c.status();}

}
Status emit_fields(ProjectionWriter& w,const MilitaryTacticLearningState& s){auto checked=validate_military_tactic_learning_shape(s);if(!checked.ok)return checked;w.sequence("acquisitions",s.acquisitions,[](auto& sink,const auto& f){return sink.object("",[&](auto& row){return emit_acquisition(row,f);});});w.sequence("practices",s.practices,[](auto& sink,const auto& f){return sink.object("",[&](auto& row){return emit_practice(row,f);});});w.order_fields(s.field_order);return w.status();}
BoundaryValue encode(const MilitaryTacticLearningState& s){BoundaryValue out;BoundaryProjectionWriter sink(out);auto checked=sink.object("",[&](auto& w){return emit_fields(w,s);});if(checked.ok)checked=sink.finish();if(!checked.ok)boundary::fail(checked.error.original.code,checked.error.original.path);return out;}
Outcome<MilitaryTacticLearningState> decode(const BoundaryValue& v){try{auto unique=military_officer_codec::validate_json_unique_keys(v);if(!unique.ok)return {false,{},unique.error};boundary::fields(v,{"acquisitions","practices"},{},"military_tactic_learning");MilitaryTacticLearningState s;s.field_order=boundary::order(v);for(const auto& f:boundary::array(boundary::field(v,"acquisitions","military_tactic_learning"),"acquisitions"))s.acquisitions.push_back(read(f));for(const auto& f:boundary::array(boundary::field(v,"practices","military_tactic_learning"),"practices"))s.practices.push_back(read_practice(f));auto checked=validate_military_tactic_learning_shape(s);return checked.ok?Outcome<MilitaryTacticLearningState>{true,std::move(s),{}}:Outcome<MilitaryTacticLearningState>{false,{},checked.error};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Status visit(CodecVisitor& c,MilitaryTacticLearningState& s,std::uint32_t version){if(version!=1)return c.reject("MilitaryTacticLearningCodecVersionMismatch");c.sequence("acquisitions",s.acquisitions,[](auto& child,auto& fact){return walk(child,fact);});c.sequence("practices",s.practices,[](auto& child,auto& fact){return walk(child,fact);});common_checkpoint::strings(c,"field_order",s.field_order);if(!c.status().ok)return c.status();auto checked=validate_military_tactic_learning_shape(s);return checked.ok?c.status():c.reject(checked.error.original.code,checked.error.original.path);}
}
